import{z as B,x as A,o as l,c as d,q as s,j as n,D as e,d as t,s as r,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"虚拟填充与密度规则","description":"","frontmatter":{"title":"虚拟填充与密度规则","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dummy-fill-density.md","filePath":"litho/dummy-fill-density.md","lastUpdated":1791413859000}'),m={name:"litho/dummy-fill-density.md"};function p(u,a,D,h,f,C){const i=A("Mermaid");return l(),d("div",null,[a[2]||(a[2]=s('<h1 id="虚拟填充与密度规则" tabindex="-1">虚拟填充与密度规则 <a class="header-anchor" href="#虚拟填充与密度规则" aria-label="Permalink to &quot;虚拟填充与密度规则&quot;">​</a></h1><div class="epigraph"><p>晶圆要的不是漂亮的版图，是均匀的版图：密度差 10% 的两块区域，CMP 之后高低差能毁掉整层光刻。</p><footer>—— 据 ITRS 密度规则演进；TSMC/Intel 先进节点 design rule manual 惯例</footer></div><p><a href="/litho/spacer-etch-sadp">间隔层刻蚀与 SADP</a>要求图形规律，本课讲反向约束：版图太「空」也不行。缺口是<strong>虚拟填充与密度规则</strong>——在真实电路之间塞进永远不通电的假图形，让整片晶圆的图形密度落在工艺窗口内。它是 CMP、刻蚀与光刻共同的隐形契约。本课不做填充算法的实现细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个工艺环节惩罚密度不均。CMP：抛光速率随图形密度变化，密度高的区域磨得慢——晶圆翘曲、下层光刻离焦。刻蚀：负载效应使开口密度高的区域刻得慢（反应基被密集开口区局部耗尽，微负载效应），图形顶失真。光刻：构图密度影响显影与衍射环境，边缘与中心 CD 漂移。缺口：<strong>密度上限与下限规则</strong>（如每 1μm² 窗口内 20–70%）及其自动化执行。</p><p><span class="marginnote">术语翻译：dummy fill（虚拟填充）= 不连接任何网络的假图形；density window（密度窗口）= 工艺允许的局部密度区间；fill 层次问题 = 填充图形与邻近真实图形的寄生耦合。</span></p><p><span class="marginnote">数字实例：金属层规则「任意 2μm 窗口内金属面积 25–70%」。某 SRAM 区实测 75%（超上限）→ 抽线；某标准单元行间区 10%（低下限）→ 塞 dummy 线。塞完后 CMP 高差从 40nm 降到 8nm，下一层光聚焦裕量回来了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>填充流水线四步：算密度图（滑动窗口栅格）；识别违规窗口；在允许轨道内布 dummy（保间距、避天线、避耦合——能接地就接地）；验证（寄生提取把 dummy 算进电容、密度规则 LVS 复查）。先进节点的变体：<strong>多层协同填充</strong>（同一 x,y 在 M1/M2/M3 错开堆叠，防通孔对齐假图形形成短路风险）与<strong>符号化填充</strong>（填充图形带 dummy 标记，工具链识别其非电属性）。</p>',9)),(l(),n(o,null,{default:e(()=>[r(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%89%88%E5%9B%BE%20%2B%20%E5%AF%86%E5%BA%A6%E8%A7%84%E5%88%99%22%5D%20--%3E%20B%5B%22%E6%BB%91%E5%8A%A8%E7%AA%97%E5%8F%A3%E7%AE%97%E5%AF%86%E5%BA%A6%E5%9B%BE%22%5D%0A%20%20B%20--%3E%20C%7B%22%E8%BF%9D%E8%A7%84%E7%AA%97%E5%8F%A3%3F%22%7D%0A%20%20C%20--%3E%7C%22%E8%B6%85%E9%AB%98%22%7C%20D%5B%22%E6%8A%BD%E7%9C%9F%E5%AE%9E%E7%BA%BF%E6%88%96%E7%B2%BE%E7%AE%80%22%5D%0A%20%20C%20--%3E%7C%22%E8%BF%87%E4%BD%8E%22%7C%20E%5B%22%E5%B8%83%20dummy%20%E5%A1%AB%E5%85%85%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%97%B4%E8%B7%9D%2F%E5%A4%A9%E7%BA%BF%2F%E8%80%A6%E5%90%88%E6%A3%80%E6%9F%A5%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%AF%84%E7%94%9F%E6%8F%90%E5%8F%96%20%2B%20LVS%20%E5%A4%8D%E6%9F%A5%22%5D%0A%20%20D%20--%3E%20G%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像贴地砖前先找平——房间有的地方瓷砖密、有的地方空一大块，水泥（CMP）干得不均匀，地面必高低不平；dummy fill 是在空处补「假瓷砖」（不通电），让整个地面受力均匀，真实瓷砖（电路）才铺得平。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"CMP 的力学机制：抛光垫压在「凸起」处压力集中——图形稀疏区上方氧化层未被图形「顶住」，磨除更快，形成碟形凹陷（dishing）；图形密集区则侵蚀（erosion）。密度均匀化让压力场均匀，碟陷与侵蚀同步消失。光刻的机制：光刻胶显影的「负载效应」与衍射的局部环境都依赖构图密度，密度图成为 source-mask 优化的输入之一。寄生机制是暗面：dummy 与邻近信号线的耦合电容让时序模型失真——先进节点的做法是把 dummy 建进提取库，让签核「看见」假图形；接地 dummy 则直接并进电源网络。",-1)),(l(),n(o,null,{default:e(()=>[r(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E4%B8%BA%E4%BD%95%20CMP%20%E6%81%A8%E5%AF%86%E5%BA%A6%E5%B7%AE%3F%22%7D%20--%3E%20R%5B%22%E5%87%B8%E8%B5%B7%E5%8F%97%E5%8A%9B%E9%9B%86%E4%B8%AD%22%5D%0A%20%20R%20--%3E%20S%5B%22%E7%A8%80%E7%96%8F%E5%8C%BA%20dishing%20%2F%20%E5%AF%86%E9%9B%86%E5%8C%BA%20erosion%22%5D%0A%20%20S%20--%3E%20T%5B%22%E5%9D%87%E5%8C%80%E5%8C%96%20%E2%86%92%20%E5%8E%8B%E5%8A%9B%E5%9C%BA%E5%B9%B3%22%5D%0A%20%20U%7B%22%E5%AF%84%E7%94%9F%E6%80%8E%E4%B9%88%E7%AE%97%3F%22%7D%20--%3E%20V%5B%22dummy%20%E5%85%A5%E6%8F%90%E5%8F%96%E5%BA%93%22%5D%0A%20%20V%20--%3E%20W%5B%22%E7%AD%BE%E6%A0%B8%E7%9C%8B%E8%A7%81%E5%81%87%E5%9B%BE%E5%BD%A2%22%5D%0A%20%20X%5B%22%E6%8E%A5%E5%9C%B0%20dummy%22%5D%20--%3E%20Y%5B%22%E5%B9%B6%E8%BF%9B%E7%94%B5%E6%BA%90%E7%BD%91%2C%20%E5%85%8D%E6%8F%90%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：把 dummy fill 当成「事后补丁」——现代流程它是签核前置条件，密度违规会直接 DRC 挂掉；另一误区是「dummy 越多越好」——过填会拉高耦合、加剧蚀刻负载的反向问题，目标是进窗口不是顶上限。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>密度规则的层次：从单层的 1D 规则（SETR 风格）进化到多层的 3D 联合规则（相邻层密度耦合影响 CMP）。EUV 时代的新矛盾：stochastic 缺陷对构图密度敏感，填充策略要与 EUV 光子统计重新谈判。设计侧的怨恨：填充吃掉布线轨道、拖累时序收敛——EDA 的答案是把 fill 从「版图完成后」提前到「布局布线中」（in-route fill），并让综合工具感知密度。与<a href="/litho/reticle-field-limit">掩模版与场域极限</a>的接续：版图在拼进场域时，密度图也是拼接优化的输入——从窗口到全场的密度叙事这才完整。</p><p><span class="marginnote">直觉类比：密度规则像「剧本的排练均匀度要求」——主角戏太重（密集区）与冷场太久（稀疏区）都毁演出；dummy fill 是给配角加戏份（假图形），不说话（不通电）但让整台戏节奏均匀。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>密度不均的三宗罪：CMP 碟陷侵蚀、刻蚀负载、光刻 CD 漂移。</li><li>dummy fill 四步：量密度、找违规、布假图形、寄生复查。</li><li>现代形态：in-route fill、多层协同、EUV stochastic 重谈判。</li><li>出处：ITRS/Lithography 密度规则章节；CMP 机制文献（Fu–Chandra 模型）；各节点 DRML 实例。</li></ul>',6))])}const y=B(m,[["render",p]]);export{c as __pageData,y as default};
